/// <summary>
/// Extension of RetailPricingSimulator
/// </summary>
[ExtensionOf(classStr(RetailPricingSimulator))]
final class METRetailPricingSimulator_Extension
{

}

Method.Source:
    /// <summary>
    /// CoC
    /// </summary>
    protected void updatePriceAndDiscountsInDbTable()
    {
        next updatePriceAndDiscountsInDbTable();

        this.metAddAdditionalDetail();  // MPJ-26540

    }

    /// <summary>
    /// MPJ-26540 Add charges to simulation header
    /// </summary>
    private void metAddAdditionalDetail()
    {
        RetailPricingSimulatorSalesLine simSalesLine;
        InventTable                     inventTable;
        InventTableModule               inventTableModuleInvent;
        CustTable                       custTable;

        ttsbegin;

        //DCP 08/08/2022 Code cleanup
        while select forupdate METChargesAmount, METTaxAmountTotal, METUnitOfMeasureConversion, METTotalCharges, METTaxAmountPerUnit,
                                METLandedCostAmount, METTotalSalesPrice, METMarginPercent, METBaseInventoryCost, METTaxAmountLCExclusions, 
                                METTotalChargesTax, Product, Quantity, RetailPricingSimulatorSalesTransaction, SalesPrice, UoM, RecId
            from    simSalesLine
            where   simSalesLine.RetailPricingSimulatorSalesTransaction  == psSalesTransaction.RecID
        {
            inventTable             = InventTable::findByProduct(simSalesLine.Product);
            inventTableModuleInvent = inventTable.inventTableModuleInvent();
            custTable               = CustTable::find(psSalesTransaction.CustAccount);
            
            this.metAddCharges(simSalesLine, inventTable, custTable);
            this.metAddTax(simSalesLine, inventTable, custTable);
            
            // UoM
            Qty conversionToInvUnit;
            var uomConversion = UnitOfMeasureConversion::findByConversion(simSalesLine.UoM, 
                                                                            UnitOfMeasure::findBySymbol(inventTableModuleInvent.UnitId).RecId,
                                                                            simSalesLine.Product);
            
            if(uomConversion)
            {
                simSalesLine.METUnitOfMeasureConversion = uomConversion.displayQuickFormulaWithLocalSeparators();
                conversionToInvUnit = uomConversion.Factor;
            }

            // Summary/total fields
            Price pricePerUnit = simSalesLine.SalesPrice / (simSalesLine.Quantity ? simSalesLine.Quantity : 1);

            simSalesLine.METTaxAmountTotal  += simSalesLine.METTotalChargesTax;
            simSalesLine.METTaxAmountPerUnit = simSalesLine.METTaxAmountTotal / (simSalesLine.Quantity ? simSalesLine.Quantity : 1);
                   
            simSalesLine.METLandedCostAmount = (simSalesLine.SalesPrice + simSalesLine.METTotalCharges + simSalesLine.METTaxAmountLCExclusions) / 
                                                (simSalesLine.Quantity ? simSalesLine.Quantity : 1) / 
                                                (conversionToInvUnit ? conversionToInvUnit : 1);
                
            simSalesLine.METTotalSalesPrice     = simSalesLine.SalesPrice + simSalesLine.METTotalCharges + simSalesLine.METTaxAmountTotal;
            
            simSalesLine.METBaseInventoryCost   = GUPItemBasePrice::findCurrent(
                inventTable.ItemId,
                GUPBasePriceType::BasePriceInventoryCost,
                simSalesLine.InventDimId,
                today()).Price;
            
            if(pricePerUnit + simSalesLine.METChargesAmount)
            {
                simSalesLine.METMarginPercent       =
                    (pricePerUnit + simSalesLine.METChargesAmount - simSalesLine.METBaseInventoryCost) /
                    (pricePerUnit + simSalesLine.METChargesAmount) * 100;
            }
            
            simSalesLine.update();
        }

        ttscommit;
    }

    /// <summary>
    /// Add tax calculation
    /// </summary>
    /// <param name = "_simSalesLine">Retail simulator Sales line</param>
    /// <param name = "_inventTable">Inventory table</param>
    /// <param name = "_custTable">Customer table</param>
    private void metAddTax(RetailPricingSimulatorSalesLine _simSalesLine, InventTable _inventTable, CustTable _custTable)
    {
        CustTable           custTable       = _custTable;
        InventTable         inventTable     = _inventTable;
        InventTableModule   inventTableModuleSales   = inventTable.inventTableModuleSales();
        Amount              taxAmount;
        Tax                 tax;
        TransDate           taxDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        // All tax codees
        tax = Tax::construct();
        taxAmount = tax.taxCalcWithoutSource(custTable.TaxGroup,
                                            inventTableModuleSales.TaxItemGroupId,
                                            taxDate,
                                            psSalesTransaction.ChannelCurrency,
                                            _simSalesLine.SalesPrice,
                                            TaxModuleType::Sales);

        _simSalesLine.METTaxAmountTotal = taxAmount;
        
        // Calculation with landed cost tax code exclusions
        tax = Tax::construct();
        tax.parmMetExcludeBasedOnLandedCostCalcFlag(true);

        taxAmount = tax.taxCalcWithoutSource(custTable.TaxGroup,
                                            inventTableModuleSales.TaxItemGroupId,
                                            taxDate,
                                            psSalesTransaction.ChannelCurrency,
                                            _simSalesLine.SalesPrice,
                                            TaxModuleType::Sales);

        _simSalesLine.METTaxAmountLCExclusions = taxAmount;
        
    }

    /// <summary>
    /// Add charges detail
    /// </summary>
    /// <param name = "_simSalesLine">Retail simulator Sales line</param>
    /// <param name = "_inventTable">Inventory table</param>
    /// <param name = "_custTable">Customer table</param>
    private void metAddCharges(RetailPricingSimulatorSalesLine _simSalesLine, InventTable _inventTable, CustTable _custTable)
    {
        CustTable                               custTable   = _custTable;
        InventTable                             inventTable = _inventTable;
        
        MarkupTrans                             markupTrans;
        MarkupTable                             markupTable;
        METRetailPricingSimulatorMarkupTrans    simMarkupTrans;
        TransDate                               taxDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        MarkupAmount                            calculatedAmount;

        delete_from simMarkupTrans
            where   simMarkupTrans.SimulatorSalesLine == _simSalesLine.RecId;

        Markup::insertMarkupTrans(HeadingLine::Line,
                                    MarkupModuleType::Cust,
                                    psSalesTransaction,
                                    custTable.AccountNum,
                                    custTable.MarkupGroup,
                                    custTable.Currency,
                                    custTable.languageId(),
                                    inventTable.ItemId);

        _simSalesLine.METChargesAmount  = 0;
        _simSalesLine.METTotalCharges   = 0;

        RecordInsertList insertList = new RecordInsertList(tableNum(METRetailPricingSimulatorMarkupTrans));

        while select markupTrans        //leaving 'select all' as is. MarkupTrans record buffer used repeatedly in multiple method calls
            where   markupTrans.TransTableId    == psSalesTransaction.TableID
            &&      markupTrans.TransRecId      == psSalesTransaction.RecID
            
        join    TaxItemGroup
            from    markupTable
            where   markupTable.MarkupCode      == markupTrans.MarkupCode
            &&      markupTable.ModuleType      == MarkupModuleType::Cust
        {
            calculatedAmount = Markup::calcTrans(markupTrans,
                                                _simSalesLine.Quantity,
                                                _simSalesLine.SalesPrice,
                                                0,      // Intercompany price requirements?
                                                taxDate);

            simMarkupTrans.clear();
            simMarkupTrans.SimulatorSalesTransaction    = psSalesTransaction.RecID;
            simMarkupTrans.SimulatorSalesLine           = _simSalesLine.RecId;
            simMarkupTrans.MarkupCode                   = markupTrans.MarkupCode;
            simMarkupTrans.MarkupCategory               = markupTrans.MarkupCategory;
            simMarkupTrans.Value                        = markupTrans.Value;
            simMarkupTrans.CalculatedAmount             = calculatedAmount;

            if(simMarkupTrans.MarkupCategory == MarkupCategory::Fixed)
            {
                simMarkupTrans.AmountPerUnit    = simMarkupTrans.CalculatedAmount;
            }
            else
            {
                simMarkupTrans.AmountPerUnit    = simMarkupTrans.CalculatedAmount / (_simSalesLine.Quantity ? _simSalesLine.Quantity : 1);
            }

            
            simMarkupTrans.TaxAmount = Tax::calcTaxAmount(custTable.TaxGroup,
                                                            markupTable.TaxItemGroup,
                                                            taxDate,
                                                            psSalesTransaction.ChannelCurrency,
                                                            simMarkupTrans.CalculatedAmount,
                                                            TaxModuleType::Sales);

            insertList.add(simMarkupTrans);

            _simSalesLine.METTotalCharges       += simMarkupTrans.CalculatedAmount;
            _simSalesLine.METChargesAmount      += simMarkupTrans.AmountPerUnit;
            _simSalesLine.METTotalChargesTax    += simMarkupTrans.TaxAmount;
        }
        insertList.insertDatabase();

        delete_from markupTrans
            where   markupTrans.TransTableId    == psSalesTransaction.TableID
            &&      markupTrans.TransRecId      == psSalesTransaction.RecID;
    }
